/* PLAYM3ANA selectable profile characters (original 3D avatars). Shared by all redesign pages.
   The user pick is stored in localStorage "pm_avatar" (index 0-9, default 0). */
window.PM_AVATARS = [
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,"
];
window.PM_getAvatar = function () {
  var i = parseInt(localStorage.getItem("pm_avatar") || "0", 10);
  if (isNaN(i) || i < 0 || i >= window.PM_AVATARS.length) i = 0;
  return window.PM_AVATARS[i];
};
